{

"kind": "propose",
"summary": "Adjust liveness probe timeout to match application startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeout (2s) is insufficient for the application's 46s startup time.",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "open"
  },
  {
    "root_cause_class": "application_bug",
    "summary": "The app crashes due to invalid currency code processing.",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "open"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow 5s for the application to respond to liveness probes after startup.",
  "rationale": "The application takes 46s to start but is killed after 2s. Increasing the liveness probe timeout to 5s would prevent premature termination. The logs confirm the app is operational before crashing, indicating the probe timeout is the immediate cause.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["probe_kills", "killed_during_startup"]
}
}
